#include "stdlib/blas/base/drotg.h"
#include <stdio.h>

int main( void ) {
	double a[] = { 0.3, 0.0, -0.0, 1.0, -1.0, 3.14, -3.14 };
	double b[] = { 0.4, 0.0, -0.0, 1.0, -1.0, 3.14, -3.14 };

	double c = 0.8;
	double s = 0.6;
	int i;

	// Constructs a Givens plane rotation
	for ( i = 0; i < 7; i++ ) {
		c_drotg( &a[i], &b[i], &c, &s );
		printf( "a: %lf, b: %lf, c: %lf, s: %lf\n", a[i], b[i], c, s );
	}
}
